-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('58147926-186e-5bc0-8dd5-44c2a9a71607'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'Comment s’écrit une question en espagnol ?', 'mcq', '["Avec un ¿ à l’ouverture et un ? à la fermeture","Avec un seul ? final","Avec un ¿ seulement","Avec « est-ce que » puis un ?"]'::jsonb, 0, 'Le ¿ se place au début de la partie interrogée, pas forcément de la phrase.', 1),
    ('66efacf8-73fb-5ec8-a300-e3e994e16d2d'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'Les mots interrogatifs espagnols portent tous un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est lui qui distingue *dónde* (interrogatif) de *donde* (relatif).', 2),
    ('e93df831-555f-5b73-8579-27da9f996293'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'Que demande « cuál » plutôt que « qué » ?', 'mcq', '["Un choix dans un ensemble","Une définition","Une cause","Une quantité"]'::jsonb, 0, '*¿Cuál prefieres?* suppose plusieurs possibilités déjà connues.', 3),
    ('fee81729-f447-564a-9178-9be716daa3c9'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'Comment traduire « Pourquoi pleures-tu ? » ?', 'mcq', '["¿Por qué lloras?","¿Porque lloras?","¿Porqué lloras?","¿Por que lloras?"]'::jsonb, 0, 'En deux mots et avec l’accent : c’est la question, pas la réponse.', 4),
    ('b0f94f2a-aa70-5b2d-99eb-db954cc5aa5e'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, '« El porqué » est un nom masculin qui signifie « la raison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*No entiendo el porqué de su decisión.*', 5),
    ('02f1a6cc-f70d-5f1a-afd1-1e4f414b1dfc'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'Dans « No sé dónde está », l’accent sur « dónde »…', 'mcq', '["Se maintient malgré l’absence de point d’interrogation","Disparaît","Devient facultatif","Se déplace"]'::jsonb, 0, 'C’est une interrogation indirecte : l’accent reste, les signes ¿ ? partent.', 6),
    ('fc6074c7-c335-5219-9aff-82dd1d07659c'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'L’espagnol exige l’inversion du sujet dans toute question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*¿Tú hablas español?* est parfaitement correct : l’intonation suffit.', 7),
    ('9c95a8c8-deb2-5de8-a838-7fc2ba63bbe5'::uuid, '3f4cbc7c-4ea3-59cb-9a36-01bb8536e207'::uuid, 'Devant un nom, l’espagnol préfère…', 'mcq', '["Qué (¿Qué día es hoy?)","Cuál (¿Cuál día es hoy?)","Quién","Cuánto"]'::jsonb, 0, '*¿Cuál día?* est un calque du français à éviter.', 8),
    ('79629408-874d-53a1-9b26-778c97181d83'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, 'Où se place « no » dans la phrase ?', 'mcq', '["Juste devant le verbe","À la fin de la phrase","Après le verbe","Devant le sujet"]'::jsonb, 0, 'Seuls les pronoms compléments peuvent s’intercaler : *No te lo digo.*', 1),
    ('cc4361c4-0cf8-59cf-b27f-e3c2e648bd8a'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, 'Comment traduire « je ne vois rien » ?', 'mcq', '["No veo nada","Veo nada","No veo","Nada veo no"]'::jsonb, 0, 'La double négation est obligatoire quand le mot négatif suit le verbe.', 2),
    ('56333e91-ff89-5375-80d1-b1efe64235ac'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, '« Nadie viene » est incorrect : il manque le « no ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand le mot négatif précède le verbe, le *no* disparaît.', 3),
    ('9ecadf62-02d6-55e2-9cb9-cc1cb6466164'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, 'Que signifie « tampoco » ?', 'mcq', '["Non plus","Encore","Déjà","Jamais"]'::jsonb, 0, '*A mí tampoco me gusta* : à moi non plus.', 4),
    ('9e39d4ec-e5fc-5d78-a36a-cb35bd686e1c'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, 'Comment dit-on « ne… plus » ?', 'mcq', '["Ya no","Todavía no","Nunca","Ni"]'::jsonb, 0, '*Ya no fumo* : je ne fume plus. *Todavía no* signifie « pas encore ».', 5),
    ('f813679b-b1df-5d49-b1b1-33fb52254a41'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["Sino","Pero","Porque","Aunque"]'::jsonb, 0, '*No es francés sino español.* *Pero* oppose sans rectifier.', 6),
    ('4a8c75da-3d93-5f49-9fbe-87182453757f'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, '« Ninguno » s’apocope en « ningún » devant un masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ningún libro*, mais *ninguna casa* et *ninguno de ellos*.', 7),
    ('3d8594d1-d28d-5eef-af26-f7feba112069'::uuid, '73f3819a-cdd1-5e8a-bff8-45c00060c02a'::uuid, 'Devant un verbe conjugué, « sino » devient…', 'mcq', '["Sino que","Sino de","Sino a","Sino el"]'::jsonb, 0, '*No canta sino que grita.*', 8),
    ('4f61dd61-6710-5910-8e8a-eb965f3fda42'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, 'Quelle relative s’écrit entre virgules ?', 'mcq', '["L’explicative","La déterminative","Les deux","Aucune"]'::jsonb, 0, 'L’explicative ajoute une information supprimable.', 1),
    ('4310261f-db2f-5fd2-ba45-091151432585'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, '« Busco una secretaria que hable inglés » emploie le subjonctif parce que…', 'mcq', '["L’antécédent est indéfini : elle reste à trouver","L’antécédent est connu","La relative est explicative","Le verbe est irrégulier"]'::jsonb, 0, 'Avec un antécédent réel, l’indicatif : *que habla inglés*.', 2),
    ('5ba7927f-6a18-5d88-9312-1db7b22d0064'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, 'La virgule d’une relative ne change pas le sens de la phrase.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Los alumnos que estudian* ne désigne pas les mêmes élèves que *los alumnos, que estudian*.', 3),
    ('a317188b-0c17-50d8-9ced-1e4efe891940'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo en","La casa vivo en que","La casa en vivo que"]'::jsonb, 0, 'La préposition précède toujours le relatif en espagnol.', 4),
    ('c041d75b-b12b-5b56-bd2e-184d6574521b'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, 'Après « No conozco a nadie que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au gérondif"]'::jsonb, 0, 'La négation rend l’antécédent inexistant, donc indéfini.', 5),
    ('6719460f-fee2-57c7-9645-c7fe6eb5d362'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, 'Pour renvoyer à une idée entière, on emploie…', 'mcq', '["Lo que","El que","Quien","Cuyo"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 6),
    ('ff4588f0-9175-5010-856c-15738fa96784'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, 'Dans une relative déterminative, on emploie normalement « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Quien* est réservé aux explicatives et aux emplois avec préposition.', 7),
    ('70fdabd2-f530-55cd-8eaf-b532521e55ae'::uuid, '688e6417-d25d-5690-b7a3-da67d866a478'::uuid, '« El que quiera, que venga » se traduit par…', 'mcq', '["Que celui qui veut vienne","Ce qu’il veut, qu’il vienne","Celui qu’il veut vient","Il veut qu’il vienne"]'::jsonb, 0, 'Relatif sans antécédent exprimé, suivi du subjonctif.', 8),
    ('598b5b9a-c096-5fc9-9aa6-c268a4b49a88'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, 'Après « Quiero que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au conditionnel"]'::jsonb, 0, 'La volonté commande le subjonctif : *Quiero que vengas.*', 1),
    ('549abce2-45ea-5ea9-a5b9-a63cd90ebf3a'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, '« Creo que viene » et « No creo que venga » emploient le même mode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nier la certitude fait passer l’indicatif au subjonctif.', 2),
    ('d2d4552a-caaf-5943-bc0b-bfc7537e39f2'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, 'Comment dit-on « je veux venir » (même sujet) ?', 'mcq', '["Quiero venir","Quiero que venga","Quiero que vengo","Quiero de venir"]'::jsonb, 0, 'Même sujet : infinitif, sans *que*.', 3),
    ('1d2c6e8c-970f-590d-80bf-05531886ef7c'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, 'Après « Es necesario que… », on emploie…', 'mcq', '["Le subjonctif","L’indicatif","Le gérondif","Le participe"]'::jsonb, 0, 'Le jugement impersonnel commande le subjonctif : *que estudies*.', 4),
    ('ee9caed3-88c6-5b53-a240-824151d927eb'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, '« Ojalá » est toujours suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ojalá llueva* : c’est l’expression du souhait par excellence.', 5),
    ('214836c5-23d2-5d7c-b697-675d2610ac33'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, 'Quand le verbe principal est au passé, le subjonctif présent devient…', 'mcq', '["L’imparfait du subjonctif","Le passé simple","Le conditionnel","Le futur"]'::jsonb, 0, '*Quería que vinieras* — les formes en -ra et en -se sont équivalentes.', 6),
    ('3501cba4-b19f-53b9-a715-54b0dd96b2c5'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, 'Après « Dudo que… », on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le doute appelle le subjonctif : *Dudo que sea verdad.*', 7),
    ('fc5fe541-807c-53c2-be90-b64a5c898d9e'::uuid, '95442aed-9f64-5d83-b6c5-e1b1fb426c44'::uuid, 'Le « que » de la complétive peut être supprimé en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se maintient toujours : *Espero que me llames.*', 8),
    ('9ec0bc7d-a187-51c2-9c7f-1e4fb3f25330'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, 'Quel est le genre de « la sangre » ?', 'mcq', '["Féminin","Masculin","Neutre","Les deux"]'::jsonb, 0, 'Piège classique : le français dit « le sang ».', 1),
    ('2fd609a4-07f0-5124-80a5-97dabfd4bd45'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, 'Les noms en « -ción » et « -dad » sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La canción*, *la ciudad*, *la libertad*.', 2),
    ('eb3a1ce1-5b87-5825-84e3-f2365692455b'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, 'Quel est le genre de « el problema » ?', 'mcq', '["Masculin, malgré le -a final","Féminin","Variable","Neutre"]'::jsonb, 0, 'Comme *el tema*, *el idioma*, *el sistema* : origine grecque.', 3),
    ('e23cac5c-5378-5566-8dd5-37ebc0773fbc'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, 'Quel est le pluriel de « lápiz » ?', 'mcq', '["Lápices","Lápizs","Lápizes","Lápiz"]'::jsonb, 0, 'Le -z devient -c devant -es.', 4),
    ('00d5d943-310b-5713-9cfa-82ed3a78c62d'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, '« El lunes » au pluriel devient « los lunes ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mots en -s non accentués sur la dernière syllabe sont invariables.', 5),
    ('e726fba7-6752-5974-bef0-8ed460b99acc'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, 'Quel est le pluriel de « el examen » ?', 'mcq', '["Los exámenes","Los examenes","Los exámens","Los examen"]'::jsonb, 0, 'L’accent écrit apparaît pour conserver la même syllabe tonique.', 6),
    ('5b1bb047-9b25-577f-a394-3e1f544a5f21'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, '« El color » est masculin en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que le français hésite : la couleur est féminine.', 7),
    ('8a5b1b8d-4b6d-5531-b861-e8d50341e424'::uuid, '15cc7ac0-6e96-5e52-a785-0d14d8c81167'::uuid, 'Comment se forme le pluriel après une consonne ?', 'mcq', '["On ajoute -es","On ajoute -s","On ne change rien","On double la consonne"]'::jsonb, 0, '*Papel → papeles*, *ciudad → ciudades*.', 8),
    ('50b23a5d-2313-55aa-ab7f-a78425430809'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, 'Quelles sont les deux contractions de l’espagnol ?', 'mcq', '["Al et del","Al, del et col","Del seulement","Al, del, pel"]'::jsonb, 0, '*a + el = al*, *de + el = del*.', 1),
    ('6ccf2eb5-9443-5a1f-8013-9d428c330cf9'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, 'Pourquoi dit-on « el agua » ?', 'mcq', '["Le nom féminin commence par un a- tonique","Le nom est masculin","C’est une exception isolée","L’article est neutre"]'::jsonb, 0, 'Le mot reste féminin : *el agua fría*, *las aguas*.', 2),
    ('b885bddd-b17a-50bb-816a-9dfa0e056256'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, '« El agua » devient « los aguas » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pluriel reprend l’article féminin : *las aguas*.', 3),
    ('f41b3e49-1b66-50d1-bd5b-5fe953fac1fc'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, 'Que précède l’article neutre « lo » ?', 'mcq', '["Un adjectif, un adverbe ou un relatif","Un nom masculin","Un nom féminin","Un verbe"]'::jsonb, 0, '*Lo importante*, *lo mejor*, *lo que dices*.', 4),
    ('59014945-adf7-5af1-b08f-d7e2de1a0081'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, 'Comment dit-on « je suis professeur » ?', 'mcq', '["Soy profesor","Soy un profesor","Estoy profesor","Soy el profesor"]'::jsonb, 0, 'Pas d’article devant une profession attribut, sauf si elle est qualifiée.', 5),
    ('ceeb8aa7-5257-53b5-a7f2-52d67dd601a2'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, '« Unos amigos » signifie « quelques amis ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pluriel de l’indéfini exprime l’approximation.', 6),
    ('e2a2dbed-f242-506e-aec4-b37772ba7d54'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, 'Comment traduire « un autre jour » ?', 'mcq', '["Otro día","Un otro día","El otro día","Uno otro día"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 7),
    ('eed6a70e-fd21-5488-8056-c500bcd8d944'::uuid, '6376bca0-dc6b-5f44-83aa-328195148ffa'::uuid, '« La avenida » ne prend pas « el » parce que…', 'mcq', '["L’accent tonique ne tombe pas sur le a initial","Le mot est masculin","Le mot est pluriel","Le mot est étranger"]'::jsonb, 0, 'La règle ne vaut que pour un a- ou ha- TONIQUE.', 8),
    ('58670f5a-2419-56c8-98da-cd0430b48b3d'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, 'Combien l’espagnol a-t-il de séries de démonstratifs ?', 'mcq', '["Trois : este, ese, aquel","Deux : este et ese","Une seule","Quatre"]'::jsonb, 0, 'Elles correspondent à *aquí*, *ahí*, *allí*.', 1),
    ('9815f672-2d2a-52aa-a9e8-72a548b31841'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, 'Quel démonstratif désigne ce qui est près de l’interlocuteur ?', 'mcq', '["Ese","Este","Aquel","Esto"]'::jsonb, 0, '*Ese libro que tienes en la mano.*', 2),
    ('b82169fa-56a2-5a88-9c6f-4bcda095b2ff'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, 'Les démonstratifs neutres « esto, eso, aquello » sont invariables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ils ne sont jamais suivis d’un nom.', 3),
    ('70247536-ecc4-54e1-befa-6155c7bf011d'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, 'Comment reprendre une phrase entière ?', 'mcq', '["Par un neutre : eso","Par ese","Par esta","Par aquellos"]'::jsonb, 0, '*No vino, y eso me molestó.*', 4),
    ('7dd19b6d-6383-507b-9758-28f3bcceb342'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, 'Depuis 2010, le pronom démonstratif porte un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La RAE l’a supprimé : on écrit *este* pronom comme *este* adjectif.', 5),
    ('76867be0-7e23-5ff3-bc32-56225589b79d'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, '« Aquellos tiempos » évoque…', 'mcq', '["Une époque lointaine","L’instant présent","Le futur proche","La semaine dernière"]'::jsonb, 0, '*Aquel* marque la plus grande distance, y compris temporelle.', 6),
    ('91e3b0f2-62fb-579e-a35f-16058df7ba7e'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, 'Comment traduire « qu’est-ce que c’est ? » ?', 'mcq', '["¿Qué es esto?","¿Qué es este?","¿Qué es ésta?","¿Qué es aquel?"]'::jsonb, 0, 'La chose n’étant pas identifiée, on emploie le neutre.', 7),
    ('d6718b8c-7cd9-5cb2-aabb-4857cad18bfe'::uuid, 'c7a8d126-d788-515e-98e5-bcc781b6d06c'::uuid, '« Esta » et « estas » sont les formes féminines de « este ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin : *este / estos* ; féminin : *esta / estas*.', 8),
    ('cc5d236f-0021-5b97-8f4a-8920a6a6187b'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, 'Où se place l’adjectif espagnol par défaut ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Avant le verbe"]'::jsonb, 0, 'C’est la position qui classe objectivement : *un coche rojo*.', 1),
    ('33f38e75-411e-5c5e-96a1-902e25dd2f3c'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, '« Un gran hombre » et « un hombre grande » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier est un grand homme, le second un homme de grande taille.', 2),
    ('156304ba-482e-5ab4-ad8c-acbeeb603595'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, 'Quel adjectif a quatre formes ?', 'mcq', '["Alto (alto, alta, altos, altas)","Inteligente","Fácil","Verde"]'::jsonb, 0, 'Les adjectifs en -e ou en consonne sont invariables en genre.', 3),
    ('f73ccaec-54d5-56bd-8fb1-88614a2e48f4'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, '« Un chico y una chica simpáticos » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des noms de genres différents, l’adjectif se met au masculin pluriel.', 4),
    ('cbe03649-bd78-5f68-b4ad-d01188571843'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, 'Que signifie « un pobre hombre » ?', 'mcq', '["Un homme à plaindre","Un homme sans argent","Un homme humble","Un homme malade"]'::jsonb, 0, 'Placé après, *un hombre pobre* désigne la pauvreté matérielle.', 5),
    ('c3fd8cc5-ee7b-5c28-9db9-7f9800542cf0'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, 'Les adjectifs de nationalité forment un féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Español/española*, *inglés/inglesa*, même s’ils finissent par une consonne.', 6),
    ('b34fb29d-1883-522d-921b-3309dfe3c72c'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, '« Un viejo amigo » signifie…', 'mcq', '["Un ami de longue date","Un ami âgé","Un ancien ami fâché","Un ami d’enfance uniquement"]'::jsonb, 0, 'La place avant le nom porte l’appréciation, pas l’âge.', 7),
    ('8136210a-4508-5fe6-8961-20ddac16f229'::uuid, 'ae012020-3470-5649-8dcc-10775afa752c'::uuid, 'Un adjectif placé avant le nom exprime souvent une appréciation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La blanca nieve*, *un buen amigo* : le regard de celui qui parle.', 8),
    ('a550d823-27c3-55f3-b1a9-adaf89e27b63'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, 'Pourquoi l’espagnol omet-il souvent le pronom sujet ?', 'mcq', '["La terminaison du verbe identifie déjà la personne","C’est un usage familier","Pour aller plus vite","Le pronom n’existe pas"]'::jsonb, 0, 'On l’exprime pour insister, opposer ou lever une ambiguïté.', 1),
    ('2f1cd3d4-e215-58bc-9928-99b4a0f264b1'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, '« Usted » se conjugue à la deuxième personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la troisième : *¿Usted habla español?* — il vient de *vuestra merced*.', 2),
    ('ed96ccfb-4446-54fb-80dd-762113d4f9aa'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, 'Quel pronom remplace « vosotros » en Amérique latine ?', 'mcq', '["Ustedes","Vos","Tú","Nosotros"]'::jsonb, 0, '*Vosotros* n’y est pas employé, même entre amis.', 3),
    ('038af1e3-e070-5773-a263-c571e550eb8f'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, 'Le « voseo » consiste à employer…', 'mcq', '["Vos à la place de tú","Usted à la place de tú","Vosotros à la place d’ustedes","Nos à la place de nosotros"]'::jsonb, 0, '*Vos tenés*, *vos sos* : norme d’Argentine, d’Uruguay, du Paraguay.', 4),
    ('52f2bbde-3067-59cc-9489-077c0a249568'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, 'Comment traduire « pour moi » ?', 'mcq', '["Para mí","Para yo","Por yo","Para me"]'::jsonb, 0, 'Après préposition, *yo* devient *mí* et *tú* devient *ti*.', 5),
    ('92254ab3-940f-5da8-be1a-d2735c8e6a74'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, '« Conmigo » et « contigo » sont des formes soudées irrégulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne dit jamais « con mí » ni « con ti ».', 6),
    ('ee4bb71d-48d6-5455-9127-ff1f227cd6cb'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, 'Après « entre » et « según », quel pronom emploie-t-on ?', 'mcq', '["Tú et yo","Ti et mí","Te et me","Usted seulement"]'::jsonb, 0, '*Entre tú y yo*, *según tú* : ces prépositions font exception.', 7),
    ('cb2c0511-12c9-5e53-9631-c3c61ced71ff'::uuid, '98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, '« Yo no lo he dicho » exprime une insistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans le *yo*, la phrase serait neutre : le pronom souligne le contraste.', 8),
    ('a4fa5808-51fe-510d-86fc-89f6eb4c415a'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'Dans quel ordre se placent les pronoms compléments ?', 'mcq', '["COI puis COD","COD puis COI","Selon la longueur du mot","Indifféremment"]'::jsonb, 0, '*Me lo da*, *te la doy* : le COI passe toujours devant.', 1),
    ('8b2e1a8c-c646-5a7f-a514-c5e342a77009'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'Que devient « le » devant « lo » ?', 'mcq', '["Se","Lo","La","Les"]'::jsonb, 0, '*Se lo doy* : « le lo doy » n’existe pas.', 2),
    ('e76eecc7-7cca-5085-b4b2-11337622fbf0'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'Avec un impératif affirmatif, le pronom se soude derrière le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dámelo*, *dímelo* — et l’accent écrit apparaît.', 3),
    ('ce377038-6bb9-5a7c-8680-d72a1dfc7ebc'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'Où se place le pronom avec un impératif négatif ?', 'mcq', '["Devant le verbe","Soudé derrière","Après le sujet","En fin de phrase"]'::jsonb, 0, '*No me lo des* : l’enclise ne vaut que pour l’affirmatif.', 4),
    ('7e556675-f230-5d24-a537-7380f481cac1'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, '« Voy a decírtelo » et « Te lo voy a decir » sont tous deux corrects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec un verbe conjugué + infinitif, les deux placements sont admis.', 5),
    ('2f705c5c-490b-5f84-ae40-a9be998133f0'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'Quel pronom COD correspond à « la » (féminin) ?', 'mcq', '["La","Le","Se","Ella"]'::jsonb, 0, '*La veo* : je la vois. *Le hablo* serait un COI.', 6),
    ('b105d1de-39a4-5079-9db8-49aa3dd24e3d'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'Le redoublement du COI est une lourdeur à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : *Le doy el libro a Juan*, *A mí me gusta*.', 7),
    ('59d37daa-ae3d-563f-b318-1ef8ab98c8ca'::uuid, 'cd651f14-0bac-5ca1-ace8-6a7ba4625bae'::uuid, 'L’accent écrit sur « dámelo » sert à…', 'mcq', '["Conserver la syllabe tonique du verbe d’origine","Marquer l’impératif","Distinguer le COD du COI","Signaler un pluriel"]'::jsonb, 0, 'L’enclise allonge le mot : sans accent, la prononciation changerait.', 8),
    ('bafab2c9-fa01-5172-b150-71dfe6688ad2'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, 'Avec quoi le possessif espagnol s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Avec l’article"]'::jsonb, 0, '*Mis libros* : le -s vient des livres, pas de moi.', 1),
    ('229f1718-7a57-5f57-a70e-d9c22d5acda5'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, 'Comment traduire « je me lave les mains » ?', 'mcq', '["Me lavo las manos","Me lavo mis manos","Lavo mis manos","Me lavo mías manos"]'::jsonb, 0, 'Corps et vêtements prennent l’article défini, pas le possessif.', 2),
    ('76f59ab7-5360-50d0-8c36-41ea44aa51d3'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, '« Su » peut signifier son, sa, leur ou votre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le recours à *de él*, *de usted* pour lever l’ambiguïté.', 3),
    ('e498f89c-aed2-59ff-bd64-0981fe25b559'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, 'Comment dit-on « un ami à moi » ?', 'mcq', '["Un amigo mío","Un mi amigo","Un amigo de mí","Mi un amigo"]'::jsonb, 0, 'La forme tonique se place après le nom.', 4),
    ('0b2c882e-6d9a-56da-b914-5653a8b9beea'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, 'Quelles formes atones varient en genre ?', 'mcq', '["Nuestro et vuestro","Mi et tu","Su seulement","Toutes"]'::jsonb, 0, '*Nuestra casa*, *vuestros libros* — mais *mi* et *tu* restent invariables.', 5),
    ('4c87c68c-f92b-5a2e-80ae-8280eced336f'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, '« El mío » est un pronom possessif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article + forme tonique : *El mío es más grande.*', 6),
    ('2964a54d-6075-582a-9488-5e75796c2124'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, 'Comment traduire « il a mal à la tête » ?', 'mcq', '["Le duele la cabeza","Le duele su cabeza","Duele su cabeza","Tiene mal su cabeza"]'::jsonb, 0, 'Le pronom *le* porte déjà l’information de possession.', 7),
    ('8a6d59f0-bc6e-5494-b7e3-c274e383a2c0'::uuid, '3ec6dd5d-9773-5c37-b8ce-a8b55b491778'::uuid, 'Au vocatif, on dit « ¡Hijo mío! ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme tonique suit le nom en apostrophe : *¡Madre mía!*', 8),
    ('e4da4d9b-9127-5d92-af86-6872b5e8bce3'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, 'Avec quoi « cuyo » s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Il est invariable"]'::jsonb, 0, '*El escritor cuya novela leí* : *cuya* s’accorde avec *novela*.', 1),
    ('a90687c3-e24c-5a25-aac4-7fc10085007f'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, '« Cuyo » peut être suivi d’un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Cuyo el libro » n’existe pas : *cuyo libro* directement.', 2),
    ('52d5385e-18e1-548e-bcf8-b353aa5909e4'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, 'Quel relatif s’emploie uniquement pour des personnes ?', 'mcq', '["Quien","Que","Cuyo","Donde"]'::jsonb, 0, '*La persona con quien hablo.*', 3),
    ('9eb57b19-9cc8-53c2-a32e-b6c36d48d54b'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo","La casa cuya vivo","La casa quien vivo"]'::jsonb, 0, 'Après préposition, *que* prend l’article.', 4),
    ('d528d6d3-d74a-5268-9858-98bcc6b671d4'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, 'Pour reprendre une idée entière, on emploie « lo que » ou « lo cual ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 5),
    ('fb241e49-0381-57eb-b6c2-4b796524ae45'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, '« Los que quieran, que vengan » signifie…', 'mcq', '["Que ceux qui veulent viennent","Ceux-là veulent venir","Ils veulent qu’ils viennent","Que veulent-ils venir"]'::jsonb, 0, '*El que / los que* sans antécédent = celui qui / ceux qui.', 6),
    ('cd29f877-8b5c-56db-a2b1-9d378a42372b'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, 'Comment demander « à qui est-ce ? »', 'mcq', '["¿De quién es?","¿Cuyo es?","¿Que es de?","¿Quien es de?"]'::jsonb, 0, '*Cuyo* ne s’emploie jamais dans une question.', 7),
    ('e79168c7-94a0-5a05-b378-081ad2eb92b4'::uuid, 'd93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, '« El cual » appartient à un registre plus soutenu que « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout après une préposition longue : *la razón por la cual*.', 8),
    ('6b092e1f-12b6-54ae-baf8-5bed06d63b7d'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, 'Comment traduire « je ne vois personne » ?', 'mcq', '["No veo a nadie","No veo nadie","Veo a nadie","No veo alguien"]'::jsonb, 0, 'Double négation, et le *a* devant un COD de personne.', 1),
    ('a42a78ad-1fc8-5d1f-950f-0ab78e1ebff9'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, '« Cualquiera » s’apocope en « cualquier » devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin comme féminin : *cualquier día*, *cualquier mujer*.', 2),
    ('240cef26-b2a0-561b-849c-0f84440d0da4'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, '« Cada » peut-il se mettre au pluriel ?', 'mcq', '["Non, il est invariable","Oui : cadas","Oui au féminin seulement","Oui devant un nombre"]'::jsonb, 0, '*Cada día*, *cada dos horas* ; « chacun » se dit *cada uno*.', 3),
    ('8159217f-4b73-5c03-ab0b-f0d9f3e6a36e'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, 'Placé après le nom, « alguno » prend un sens…', 'mcq', '["Négatif renforcé","Positif renforcé","Interrogatif","Neutre"]'::jsonb, 0, '*No tengo duda alguna* = aucun doute.', 4),
    ('dff3de2b-943d-53f0-86e1-2c0d8126fd68'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, '« Todos días » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Todo* exige l’article : *todos los días*.', 5),
    ('04abe33c-8772-5196-9981-3060746016b2'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, 'Que signifie « los demás » ?', 'mcq', '["Les autres, le reste","Les mêmes","Trop nombreux","Chacun"]'::jsonb, 0, '*Los demás alumnos se fueron.*', 6),
    ('680650ff-3c39-5d83-8b42-d9fa959e4af5'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, '« Alguien » et « nadie » sont invariables et toujours singuliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne s’accordent ni en genre ni en nombre.', 7),
    ('cc6a1d16-601a-5d60-b4a4-1e35218f94bf'::uuid, '726d647a-096c-54a1-9758-4f01feac1e6b'::uuid, 'Comment dit-on « un autre livre » ?', 'mcq', '["Otro libro","Un otro libro","El otro libro","Otro el libro"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 8),
    ('ee51f0a1-0960-5eea-82a1-cb0f4613933c'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, 'Comment traduire « aussi grand que toi » ?', 'mcq', '["Tan alto como tú","Tanto alto como tú","Más alto como tú","Tan alto que tú"]'::jsonb, 0, '*Tan* devant un adjectif, *como* comme second terme.', 1),
    ('cb86b13c-c3fe-5d60-99c2-bd2fa2a5b0ce'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, 'Comment traduire « autant de livres que toi » ?', 'mcq', '["Tantos libros como tú","Tan libros como tú","Tanto libros como tú","Más libros como tú"]'::jsonb, 0, '*Tanto* devant un nom, et il s’accorde : *tantos libros*.', 2),
    ('2c7e7fee-21b5-5d98-a4b4-3066f26fb5d2'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, 'Devant un nombre, on emploie « de » et non « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Más de veinte libros*, *menos de diez euros*.', 3),
    ('e3c0813c-29ad-5fbd-8787-02e6a4622c6b'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, 'Que signifie « No tengo más que diez euros » ?', 'mcq', '["Je n’ai que dix euros","Je n’ai pas plus de dix euros","J’ai plus de dix euros","J’ai environ dix euros"]'::jsonb, 0, 'En phrase négative, *más que* signifie « seulement ».', 4),
    ('6b3d0230-a9ea-5302-a8e9-14037b80d82d'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, '« Más mejor » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les comparatifs irréguliers ne se combinent jamais avec *más*.', 5),
    ('61ed8a15-8aff-5850-b65f-b7781ea65ae9'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, 'Quel est le comparatif de « malo » ?', 'mcq', '["Peor","Más malo","Menor","Mal"]'::jsonb, 0, 'Comme *bueno → mejor*, *grande → mayor*, *pequeño → menor*.', 6),
    ('8f047514-1fce-5bfe-8cca-6e469a1296c5'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, 'Comment traduire « plus difficile qu’il n’y paraît » ?', 'mcq', '["Más difícil de lo que parece","Más difícil que parece","Más difícil como parece","Tan difícil que parece"]'::jsonb, 0, 'Quand le second terme est une proposition : *de lo que*.', 7),
    ('4ca354cf-b51b-57f9-b74e-0658fe96c19e'::uuid, '2d6c5e43-1118-5d40-b4b9-d32bd027e68e'::uuid, '« Trabaja tanto como yo » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un verbe, on emploie *tanto como*, invariable.', 8),
    ('21df5a28-2ef0-5f79-ad2e-8e65dd266f5f'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, 'Comment traduire « le plus grand du monde » ?', 'mcq', '["El más grande del mundo","El más grande en el mundo","El mucho grande del mundo","El más grande que el mundo"]'::jsonb, 0, 'Le complément du superlatif relatif se construit avec *de*.', 1),
    ('482c8846-9785-5060-98eb-0086c5284c65'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, '« Muy guapísimo » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie *muy* OU le suffixe -ísimo, jamais les deux.', 2),
    ('7aed124e-0ea9-513a-bc44-8a5fd646970e'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, 'Quel est le superlatif absolu de « rico » ?', 'mcq', '["Riquísimo","Ricísimo","Rikísimo","Ricoísimo"]'::jsonb, 0, 'Le c devient qu pour conserver le son [k].', 3),
    ('9a5928b5-1367-5c3d-904e-5ed839f77873'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, 'Quel est le superlatif absolu de « feliz » ?', 'mcq', '["Felicísimo","Felizísimo","Felisísimo","Felizmo"]'::jsonb, 0, 'Le z devient c devant le i.', 4),
    ('77d2d6dd-08c9-5706-a023-1526b7f6734d'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, '« Óptimo » est le superlatif savant de « bueno ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *pésimo* pour *malo*, *máximo* pour *grande*.', 5),
    ('7c96c5ad-bfd7-5d8e-894d-265c0d1c3a0b'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, 'Que devient le « g » de « largo » au superlatif ?', 'mcq', '["Il devient gu : larguísimo","Il disparaît","Il devient j","Il double"]'::jsonb, 0, 'Pour conserver le son [g] devant le i.', 6),
    ('03d5552d-0568-56f9-b1c5-ce4e7b6e4f10'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, 'Le superlatif relatif compare à l’intérieur d’un ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El alumno más inteligente de la clase* : l’ensemble est la classe.', 7),
    ('987059c7-ff98-5790-b61f-e4756fce0efd'::uuid, '9d341b50-d530-59e1-b402-2f3119cdd083'::uuid, 'Comment dit-on « énormément » avec un suffixe ?', 'mcq', '["Muchísimo","Muy mucho","Mucho muy","Máximo"]'::jsonb, 0, '*Mucho* prend lui aussi le suffixe -ísimo.', 8),
    ('5470bb39-2487-53ac-b07c-c1c09def2821'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, 'Quelle est la forme apocopée de « bueno » devant un nom masculin ?', 'mcq', '["Buen","Bue","Buenó","Bon"]'::jsonb, 0, '*Un buen amigo*, mais *un amigo bueno* garde la forme pleine.', 1),
    ('27074db7-ba98-5c4e-89ee-fa8f42e05964'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, '« Grande » s’apocope devant un nom féminin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Una gran mujer* : c’est le seul adjectif à s’apocoper aux deux genres.', 2),
    ('9d7baa53-98d8-5515-b16f-0d5c8fb22a5a'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, 'Comment dit-on « cent euros » ?', 'mcq', '["Cien euros","Ciento euros","Cientos euros","Cien de euros"]'::jsonb, 0, '*Ciento* s’apocope devant un nom, et devant *mil* et *millones*.', 3),
    ('ef1bea6a-e054-54b5-bfd7-290dcc61f90a'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, 'Quelle est la forme correcte : « santo Domingo » ou « Santo Domingo » ?', 'mcq', '["Santo Domingo : pas d’apocope devant To- et Do-","San Domingo","Sant Domingo","Sa Domingo"]'::jsonb, 0, 'Même exception pour *Santo Tomás* et *Santo Tomé*.', 4),
    ('48ea47ad-3997-5bb6-a9c2-4dc21e5a6840'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, '« Tercero » devient « tercer » devant un nom masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El tercer año*, comme *el primer piso*.', 5),
    ('d375974f-d8ff-593e-818b-1c9e42f4fbd5'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, 'Quelle est la forme apocopée de « cualquiera » ?', 'mcq', '["Cualquier, aux deux genres","Cualqui","Cualquiero","Il ne s’apocope pas"]'::jsonb, 0, '*Cualquier día*, *cualquier mujer*.', 6),
    ('4702fb49-e131-5f68-af39-f84471806cc0'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, '« Recién » s’emploie devant un participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Recién nacido*, *recién llegado*, *recién casados*.', 7),
    ('25e5bfe5-a2e9-5641-9552-d28bcf2bb943'::uuid, '272b2bd8-be27-5bdb-ab59-01db2472b5c9'::uuid, '« Ciento veinte » garde la forme pleine parce que…', 'mcq', '["Ciento est suivi d’un autre nombre","Ciento est féminin","Le nombre est pair","Il s’agit d’un pluriel"]'::jsonb, 0, 'L’apocope ne joue que devant un nom, *mil* ou *millones*.', 8),
    ('7691742d-d892-5d94-956f-c6af9491b22d'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, 'Combien l’espagnol a-t-il d’auxiliaires de temps composés ?', 'mcq', '["Un seul : haber","Deux : haber et ser","Deux : haber et tener","Trois"]'::jsonb, 0, 'Contrairement au français, aucune hésitation entre « être » et « avoir ».', 1),
    ('e10c9258-49b5-541d-af78-c38c9c96aeb8'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, 'Le participe passé s’accorde avec « haber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais : *la carta que he escrito*, *ellas han venido*.', 2),
    ('0cf50467-6e5b-5246-aad0-c0c393359486'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, 'Comment traduire « il y a deux livres » ?', 'mcq', '["Hay dos libros","Han dos libros","Hays dos libros","Están dos libros"]'::jsonb, 0, '*Hay* est invariable, même devant un pluriel.', 3),
    ('c1a448d0-16ae-5d2c-a201-992944adde2b'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, 'Peut-on placer un adverbe entre l’auxiliaire et le participe ?', 'mcq', '["Non, le bloc est soudé","Oui, toujours","Oui, si c’est une négation","Oui, à l’écrit seulement"]'::jsonb, 0, '*No lo he visto nunca*, jamais « he nunca visto ».', 4),
    ('9f290638-aed4-5fc6-b863-dce7e712a785'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, '« Había » est la forme passée de « hay ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et elle reste au singulier : *Había muchos alumnos.*', 5),
    ('bc2e7166-c98d-5de6-a7e7-35ec40027e2c'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, 'Que signifie « Hay que estudiar » ?', 'mcq', '["Il faut étudier","J’ai étudié","Il y a des études","Il faut que j’étudie"]'::jsonb, 0, 'Obligation impersonnelle, sans sujet exprimé.', 6),
    ('3a9dfade-0203-5851-82fb-af44435649ee'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Había + participe passé","Hubo + participe passé","Era + participe passé","Estaba + participe passé"]'::jsonb, 0, '*Había salido cuando llegué.*', 7),
    ('4b09f882-3ca3-590d-ba6d-50e44e284f4d'::uuid, 'fff8be80-9313-58d2-aa5a-834217683a22'::uuid, '« Hay un banco en la plaza » et « El banco está en la plaza » disent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Hay* pose l’existence, *estar* localise une chose déjà connue.', 8),
    ('01ba8c24-fba8-51c6-91d6-8829cd54b820'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, 'Où se place le pronom réfléchi avec un infinitif ?', 'mcq', '["Soudé derrière : levantarse","Devant l’infinitif","En fin de phrase","Devant le sujet"]'::jsonb, 0, 'Même chose au gérondif et à l’impératif affirmatif.', 1),
    ('db90027e-f3e6-587c-9bf8-6b6bd816e242'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, 'Dans « Se venden pisos », le verbe s’accorde avec « pisos ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un *se* passif : le sujet grammatical est *pisos*.', 2),
    ('abf102b9-27a8-576d-b18c-d78db6a2c205'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, 'Que signifie « Me voy » ?', 'mcq', '["Je m’en vais","Je vais bien","Je me vois","Je viens"]'::jsonb, 0, '*Ir* signifie aller, *irse* partir : le pronom change le sens.', 3),
    ('82122c36-1e46-502c-9e3b-3139cb462371'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, 'Dans un « se » impersonnel, le verbe est…', 'mcq', '["Toujours au singulier","Toujours au pluriel","Accordé au complément","À l’infinitif"]'::jsonb, 0, '*Se dice que…*, *Aquí se come bien.*', 4),
    ('49fa3fde-add2-51e9-96cb-80152517bf37'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, '« Quejarse » et « atreverse » sont des verbes essentiellement pronominaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pronom fait partie du verbe : il n’a pas de valeur réfléchie.', 5),
    ('4f789d9f-2ccf-503f-b67c-1f7c4d261634'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, 'Que signifie « Se escriben » ?', 'mcq', '["Ils s’écrivent l’un à l’autre","Ils s’écrivent eux-mêmes","On les écrit","Ils sont écrits"]'::jsonb, 0, 'Valeur réciproque : plusieurs sujets agissent l’un sur l’autre.', 6),
    ('2d35a6dc-aa5f-58a9-ab28-dc15c8afcee3'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, '« Dormirse » signifie « s’endormir ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que *dormir* signifie simplement dormir.', 7),
    ('3f7934d6-2c43-57be-8bfa-0e132aa3a547'::uuid, '4657249f-c390-54f8-a140-ac583b4605c3'::uuid, 'Dans « Se comió toda la tarta », le pronom exprime…', 'mcq', '["Une nuance d’appropriation","Une réciprocité","Une passive","Une obligation"]'::jsonb, 0, 'Le pronominal d’intensité, sans valeur réfléchie.', 8),
    ('c525d953-d0bd-505d-bca5-9ddacfabf038'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, 'Qu’est-ce qui déclenche la diphtongue ?', 'mcq', '["L’accent tonique sur la voyelle du radical","La terminaison en -ar","Le pluriel","La négation"]'::jsonb, 0, 'Quand l’accent passe sur la terminaison, la voyelle redevient simple.', 1),
    ('9ff6cfd4-bfbe-57e9-930f-0043edb412c1'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, 'Quelles personnes ne diphtonguent jamais ?', 'mcq', '["Nosotros et vosotros","Yo et tú","Él et ellos","Tú et vosotros"]'::jsonb, 0, 'Elles portent l’accent sur la terminaison : d’où la conjugaison « en botte ».', 2),
    ('a845f378-fb40-5e10-b396-565ce40b606d'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, 'Quelle est la première personne de « poder » au présent ?', 'mcq', '["Puedo","Podo","Puedo/podo","Puedes"]'::jsonb, 0, 'La diphtongue o → ue apparaît sous l’accent.', 3),
    ('c0075304-7bd3-53ad-b8c6-4e74008e416e'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, '« Jugar » est le seul verbe à diphtonguer u → ue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Juego, juegas, juega… jugamos, jugáis, juegan.*', 4),
    ('20e199ac-d3b6-5cd3-8017-17e7a5670047'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, 'La diphtongue apparaît aussi au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement au présent de l’indicatif, au subjonctif présent et à l’impératif.', 5),
    ('5cb248ca-638e-5841-b3f2-9b8fc4d455c9'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, 'Quelle est la forme de « pensar » à la première personne du pluriel ?', 'mcq', '["Pensamos","Piensamos","Pensemos","Piensemos"]'::jsonb, 0, 'L’accent tombe sur la terminaison : pas de diphtongue.', 6),
    ('9257d0bf-c924-53c8-bc5a-89b5cba4aa75'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, 'Que devient « oler » quand il diphtongue ?', 'mcq', '["Huelo, avec un h","Uelo","Ólo","Oigo"]'::jsonb, 0, 'Un h purement orthographique s’ajoute devant le ue initial.', 7),
    ('8ae2433a-1135-59c3-acb0-5e2c35465e1c'::uuid, '1ff3302f-aaed-5ecf-abd4-80c55997f946'::uuid, '« Pedir → pido » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un verbe à affaiblissement : le e devient i, il ne diphtongue pas.', 8),
    ('885d0010-329a-5382-93b5-c3089e3f43e0'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, 'À quel groupe appartiennent tous les verbes à affaiblissement ?', 'mcq', '["Aux verbes en -ir","Aux verbes en -ar","Aux verbes en -er","À tous les groupes"]'::jsonb, 0, '*Pedir, servir, repetir, seguir…* — aucun -ar ni -er.', 1),
    ('507f8e2d-5cc7-5a59-a033-4817d40f02ab'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, 'Quelle est la troisième personne du passé simple de « pedir » ?', 'mcq', '["Pidió","Pedió","Pidó","Pediró"]'::jsonb, 0, 'Dès que la terminaison contient un ió ou un ie, le e s’affaiblit.', 2),
    ('15b3a7b1-28b2-5ef9-8a86-1b345de75b30'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pida, pidas, pida, pidamos, pidáis, pidan* — y compris nosotros et vosotros.', 3),
    ('b9b47d45-794d-5c95-af1f-e1d480668724'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, 'Quel est le gérondif de « decir » ?', 'mcq', '["Diciendo","Deciendo","Diciento","Dicendo"]'::jsonb, 0, 'Le gérondif des verbes en -ir irréguliers porte l’affaiblissement.', 4),
    ('0cfbc454-2c48-5f4a-9755-60f2d70bf24a'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, '« Dormir » est un verbe mixte : diphtongue au présent, affaiblissement ailleurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Duermo* au présent, mais *durmió* et *durmiendo*.', 5),
    ('0f6f6931-ca0d-5d2f-a8d9-b57a2df0ae10'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, 'Quelle est la première personne du présent de « seguir » ?', 'mcq', '["Sigo","Siguo","Sego","Seguo"]'::jsonb, 0, 'Le u disparaît devant o et a, sinon il se prononcerait.', 6),
    ('5c474c5c-c73c-51eb-8a33-2ecbbe92bc5d'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, 'Que devient le « g » de « elegir » devant un o ?', 'mcq', '["Il devient j : elijo","Il devient gu","Il disparaît","Il double"]'::jsonb, 0, 'Pour conserver le son [x] : *elijo*, *corrijo*.', 7),
    ('cffd3239-5f5a-59a0-b057-c8bb068f072d'::uuid, 'f3c72b54-2b9b-56f5-aeae-ab879ce47c04'::uuid, '« Pedimos » porte l’affaiblissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme *pedís*, il garde le e : l’accent tombe sur la terminaison.', 8),
    ('fab8a35f-23c6-5dad-94c3-4a75b69784ed'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, 'Quel verbe employer pour la localisation d’une chose ?', 'mcq', '["Estar","Ser","Haber","Tener"]'::jsonb, 0, '*Madrid está en España* — mais un événement se situe avec *ser*.', 1),
    ('f43ba7bf-6dd4-5239-8e2d-ccc93e30cd01'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, '« Ser listo » et « estar listo » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Être malin » contre « être prêt » : deux mots différents.', 2),
    ('f868f25d-0910-54e6-8ba6-4a2dc12a6656'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, 'Comment dit-on l’heure en espagnol ?', 'mcq', '["Son las tres","Están las tres","Hay las tres","Tienen las tres"]'::jsonb, 0, 'Heure, date, prix : toujours *ser*.', 3),
    ('ce2b8e16-c240-53c0-afae-70063f4525fb'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, 'Que signifie « estar malo » ?', 'mcq', '["Être malade","Être méchant","Être mauvais","Être en colère"]'::jsonb, 0, '*Ser malo* signifie être méchant.', 4),
    ('1599b159-a889-5567-933a-bf48e995f8a5'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, '« La fiesta es en mi casa » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un événement se situe avec *ser*, à la différence d’un lieu ou d’un objet.', 5),
    ('210a70a3-3df9-529c-8340-da4d30d9b45d'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, 'Quel verbe entre dans la forme progressive ?', 'mcq', '["Estar (estoy estudiando)","Ser","Haber","Ir"]'::jsonb, 0, '*Estar* + gérondif exprime l’action en cours.', 6),
    ('1f85bd2d-569b-5eb2-9cbf-39f70bba7420'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, '« La sopa está fría » décrit un état constaté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La soupe a refroidi ; *el hielo es frío* énonce une propriété.', 7),
    ('2f7c41ca-2cb8-571f-a8c5-e655bcb5d7a6'::uuid, 'a6a48e9e-6d00-5dce-b6e0-97dfdf5f3eb8'::uuid, 'Comment dit-on « je suis d’accord » ?', 'mcq', '["Estoy de acuerdo","Soy de acuerdo","Tengo de acuerdo","Hay de acuerdo"]'::jsonb, 0, 'Expression figée avec *estar*, comme *estar de vacaciones*.', 8),
    ('6b0354fd-6aae-583d-9fe3-40b9bfd98114'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, 'Quelle est la terminaison du gérondif des verbes en -ar ?', 'mcq', '["-ando","-iendo","-yendo","-ado"]'::jsonb, 0, '*Hablar → hablando* ; les -er et -ir font *-iendo*.', 1),
    ('a6b468a0-705a-5e6c-8319-742ada42c99e'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, 'Quel est le gérondif de « leer » ?', 'mcq', '["Leyendo","Leiendo","Leendo","Leído"]'::jsonb, 0, 'Le -iendo devient -yendo après une voyelle.', 2),
    ('e9b11740-aa63-59cc-9802-83f1e99f9652'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, '« Una caja conteniendo libros » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le gérondif ne qualifie pas un nom : *una caja que contiene libros*.', 3),
    ('979fe0d0-46d4-5c1b-aafe-6f8bd1120637'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, 'Que signifie « Llevo dos años estudiando español » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié deux ans","J’emporte deux ans d’espagnol","Je vais étudier deux ans"]'::jsonb, 0, '*Llevar* + durée + gérondif exprime la durée écoulée.', 4),
    ('453a65c8-6ee0-5e09-9f18-59a7f6f94977'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, 'Après une préposition, on emploie l’infinitif et non le gérondif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Antes de salir*, *sin decir nada*, *al entrar*.', 5),
    ('d48b2dad-4635-5dc1-a9fe-7077d40630de'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, 'Comment traduire « en entrant, j’ai vu Juan » ?', 'mcq', '["Al entrar, vi a Juan","Entrando, vi a Juan","En entrando, vi a Juan","Para entrar, vi a Juan"]'::jsonb, 0, '*Al* + infinitif exprime la simultanéité.', 6),
    ('129b524c-498c-5cf5-beaf-35770521704b'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, '« Sigue lloviendo » signifie « il pleut toujours ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Seguir* + gérondif exprime la continuation.', 7),
    ('b36617cb-55ff-509b-a682-1ad48483ecc9'::uuid, 'dcbda463-458e-5e83-80a2-0f8cc3feb985'::uuid, 'Quel est le gérondif de « dormir » ?', 'mcq', '["Durmiendo","Dormiendo","Duermiendo","Durmendo"]'::jsonb, 0, 'L’affaiblissement o → u apparaît au gérondif des verbes en -ir.', 8),
    ('371dc52c-7e29-50e6-8dd3-7d89b9543d66'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'Le participe employé avec « haber » s’accorde-t-il ?', 'mcq', '["Jamais","Toujours","Seulement au féminin","Seulement au pluriel"]'::jsonb, 0, '*Ellas han llegado*, *las cartas que he escrito*.', 1),
    ('e0f997ed-76a1-5172-aef7-c36507dea488'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'Quel est le participe passé de « escribir » ?', 'mcq', '["Escrito","Escribido","Escribado","Escripto"]'::jsonb, 0, 'Comme *abrir → abierto*, *hacer → hecho*, *ver → visto*.', 2),
    ('931dc037-72db-56ee-a8ee-9c2921242554'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, '« La puerta está cerrada » comporte un accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *estar*, le participe s’accorde avec le sujet.', 3),
    ('75e25d6c-5902-5561-b1d8-0b413cc920c9'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'Quelle différence entre « fue construida » et « está construida » ?', 'mcq', '["La première décrit l’action, la seconde l’état résultant","Aucune","La première est un futur","La seconde est un passé simple"]'::jsonb, 0, '*Ser* + participe = passive d’action ; *estar* + participe = état.', 4),
    ('9ce0a07b-088d-5151-b04c-9deb7d4da770'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'Quel est le participe passé de « volver » ?', 'mcq', '["Vuelto","Volvido","Volvido/vuelto","Voltado"]'::jsonb, 0, 'Comme *resolver → resuelto*, *poner → puesto*.', 5),
    ('3904e4ba-f181-54b1-b476-33bc724431af'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'L’espagnol emploie la passive avec « ser » plus souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui préfère la tournure *se* ou la 3e personne du pluriel.', 6),
    ('ec71bca7-3312-5d0f-a826-a45e5831c08a'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'Quel participe emploie-t-on comme adjectif avec « freír » ?', 'mcq', '["Frito (patatas fritas)","Freído","Freito","Fritado"]'::jsonb, 0, 'Participe double : *he freído* aux temps composés, *frito* comme adjectif.', 7),
    ('ee6e2996-10d6-5b0f-9880-de698085e49e'::uuid, '097c20a0-b419-550f-811a-8a5c0c91547c'::uuid, 'Quel est le participe passé de « satisfacer » ?', 'mcq', '["Satisfecho","Satisfacido","Satisfaído","Satisfacto"]'::jsonb, 0, 'Formé sur *hacer → hecho*.', 8),
    ('4c606622-fd2b-5c0f-a501-01827a9aed6a'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, 'Dans « Me gustan las películas », quel est le sujet ?', 'mcq', '["Las películas","Me","Yo","Gustan"]'::jsonb, 0, 'Le verbe s’accorde avec ce qui plaît, pas avec la personne.', 1),
    ('ab8199ed-2351-5eeb-8605-3d703b9dc846'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, 'Comment traduire « j’aime lire et écrire » ?', 'mcq', '["Me gusta leer y escribir","Me gustan leer y escribir","Yo gusto leer y escribir","Me gusto leer y escribir"]'::jsonb, 0, 'Un ou plusieurs infinitifs comptent pour un singulier.', 2),
    ('de954076-6bd8-591b-a33e-f152b1f1003c'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, '« A mí me gusta » est une redondance à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : le *a mí* renforce, le pronom *me* reste obligatoire.', 3),
    ('bd58ff57-34e5-5d54-9ce2-48d195d435e9'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, 'Comment traduire « j’ai mal à la tête » ?', 'mcq', '["Me duele la cabeza","Duelo la cabeza","Tengo dolor la cabeza","Me duelo la cabeza"]'::jsonb, 0, '*Doler* se construit comme *gustar*.', 4),
    ('c15908f4-29bb-5500-b616-8e549d11b2dc'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, 'Que répondre à « Me gusta el cine » pour dire « moi aussi » ?', 'mcq', '["A mí también","A mí tampoco","A mí sí","Yo también gusto"]'::jsonb, 0, '*Tampoco* servirait à répondre à une phrase négative.', 5),
    ('797916c2-1670-5e2f-8a84-fec7be4d52d2'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, '« Me encantan los perros » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Encantar* fonctionne comme *gustar* : accord avec *los perros*.', 6),
    ('3656dfe7-f893-5e6f-93a9-e655f0e781e8'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, 'Comment renforcer « le gusta » pour préciser qu’il s’agit de Juan ?', 'mcq', '["A Juan le gusta","Juan le gusta","Le gusta Juan","A Juan gusta"]'::jsonb, 0, 'Le pronom *le* se maintient même quand le nom est exprimé.', 7),
    ('6cc1e46f-f845-53f7-a2d2-6213c8f10677'::uuid, 'eaf69002-635c-50d0-bd2a-b5efa593fec7'::uuid, 'On peut dire « me gusta muy ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit *me gusta mucho* : *muy* ne modifie jamais un verbe.', 8),
    ('9e26f8fb-4c5a-598c-b3c9-573cefaaaf1f'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, 'Quelle tournure exprime une obligation personnelle ?', 'mcq', '["Tener que + infinitif","Hay que + infinitif","Soler + infinitif","Acabar de + infinitif"]'::jsonb, 0, '*Tengo que estudiar* : l’obligation vise quelqu’un.', 1),
    ('0137b9d8-ab5e-5e5e-8f29-1530a2a98941'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, '« Hay que » est invariable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation est impersonnelle : aucun sujet, donc aucune variation en personne.', 2),
    ('c79920d4-6334-5c76-b2dd-cbdc784b4a0a'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, 'Que signifie « Debe de estar enfermo » ?', 'mcq', '["Il doit être malade (supposition)","Il doit rester malade","Il faut qu’il soit malade","Il a dû tomber malade"]'::jsonb, 0, '*Deber de* exprime la probabilité, *deber* seul l’obligation morale.', 3),
    ('70873dfd-06e1-5df3-9580-b0a1fcb2f001'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, 'Comment traduire « il faut étudier » (en général) ?', 'mcq', '["Hay que estudiar","Tengo que estudiar","Debo estudiar","Es estudiar"]'::jsonb, 0, 'L’obligation impersonnelle passe par *hay que*.', 4),
    ('c48e29fd-1c2e-53b7-b47d-b72853969297'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, 'Après « Es necesario que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Es necesario que vengas* : le jugement impersonnel commande le subjonctif.', 5),
    ('f9d2a60d-4edc-52e9-8460-52d612ff752d'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, 'Quelle nuance sépare « tenía que estudiar » et « tuve que estudiar » ?', 'mcq', '["L’imparfait laisse ouvert, le passé simple conclut","Aucune","Le premier est un futur","Le second est impersonnel"]'::jsonb, 0, '*Tuve que* dit que l’obligation a été suivie d’effet.', 6),
    ('541cffcb-94c4-5357-b8d4-b6052eb2dd78'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, '« Haber de + infinitif » appartient à un registre soutenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He de irme* : obligation atténuée, plus littéraire que *tengo que*.', 7),
    ('0fa08733-b2e0-51a8-967f-0c86461e22de'::uuid, 'a2b3f17f-909f-5dc4-bb68-25999f864adf'::uuid, 'Comment exprimer un ordre direct ?', 'mcq', '["Par l’impératif : ¡Estudia!","Par le gérondif","Par l’infinitif seul","Par le futur"]'::jsonb, 0, 'Et à la forme négative, l’impératif emprunte au subjonctif : *¡No salgas!*', 8),
    ('9c3eeaee-7e38-5170-945c-c30fdfb8110d'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, 'Que signifie « Suelo levantarme temprano » ?', 'mcq', '["J’ai l’habitude de me lever tôt","Je me lève seul","Je viens de me lever","Je dois me lever tôt"]'::jsonb, 0, '*Soler* + infinitif exprime l’habitude à lui seul.', 1),
    ('3decbd54-d067-509a-81a6-b6db625b66fe'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, 'À quels temps « soler » s’emploie-t-il ?', 'mcq', '["Au présent et à l’imparfait","À tous les temps","Au passé simple seulement","Au futur seulement"]'::jsonb, 0, 'L’habitude n’est pas un événement daté : ni passé simple, ni futur.', 2),
    ('b49271f5-fc12-53ce-a35f-257e0cd74e03'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, '« Soler » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Suelo, sueles, suele… solemos, soléis, suelen.*', 3),
    ('2508fa45-809d-5184-a1ed-6e3d41bc4539'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, 'Comment traduire « je l’ai rappelé » (une seconde fois) ?', 'mcq', '["Volví a llamarlo","Rellamé","Llamé otra vez lo","Vuelvo llamarlo"]'::jsonb, 0, '*Volver a* + infinitif remplace le préfixe « re- » du français.', 4),
    ('3c9498a1-19c6-5ea0-b50c-bbf9d6a4eac8'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, '« Acostumbrarse a » signifie « avoir l’habitude de ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme pronominale signifie « s’habituer à ».', 5),
    ('36e71632-b691-529c-bde8-9595a0bbfdae'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, 'Quel temps exprime seul l’habitude passée ?', 'mcq', '["L’imparfait","Le passé simple","Le futur","Le conditionnel"]'::jsonb, 0, '*Cuando era pequeño, jugaba al fútbol.*', 6),
    ('e92a66fc-2fab-5253-a11b-4d9709fed89a'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, '« De vez en cuando » signifie…', 'mcq', '["De temps en temps","Toujours","Jamais","Chaque fois"]'::jsonb, 0, 'Entre *a menudo* (souvent) et *casi nunca* (presque jamais).', 7),
    ('d95526ac-9387-5831-987d-1f98e203ffaa'::uuid, '06317290-42c4-5746-ba10-428a7e4dc54b'::uuid, '« Seguir + gérondif » exprime la continuation d’une action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sigo estudiando español* : je continue d’étudier l’espagnol.', 8),
    ('3dfa54a0-171d-547c-bc6c-0166ca7b914e'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, 'Que signifie « Serán las tres » ?', 'mcq', '["Il doit être trois heures","Il sera trois heures","Il était trois heures","Il faut qu’il soit trois heures"]'::jsonb, 0, 'Le futur de probabilité suppose sur le PRÉSENT.', 1),
    ('73f81bbf-f139-5dc0-82a6-a6f25d4a8c6e'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, 'Le conditionnel de probabilité porte sur…', 'mcq', '["Le passé","Le présent","Le futur","L’avenir proche"]'::jsonb, 0, '*Serían las tres cuando llegó* : il devait être trois heures.', 2),
    ('f171a790-71f3-502d-9d3f-e7c60732e53d'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, '« Puede que » est suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Puede que llueva* — sans exception.', 3),
    ('7af8996d-f1ad-5be0-9394-50af9c52c4b8'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, 'Quel mode suit « a lo mejor » ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le gérondif"]'::jsonb, 0, 'C’est le piège : à la différence de *quizás*, *a lo mejor* garde l’indicatif.', 4),
    ('8575e835-b73c-5e15-aac0-6f232567057c'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, '« Debe estudiar » et « Debe de estudiar » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier exprime l’obligation, le second la supposition.', 5),
    ('27a9df36-a917-5245-9047-a699eda541e0'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, '« Quizás venga » plutôt que « quizás viene » signale…', 'mcq', '["Une probabilité plus faible","Une certitude","Un ordre","Un futur proche"]'::jsonb, 0, 'Le subjonctif marque la réserve, l’indicatif l’assurance.', 6),
    ('3815aada-7926-5bb8-9db1-56517d0e963b'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, '« Habrá salido » suppose sur un fait accompli.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur antérieur de probabilité : il a dû sortir.', 7),
    ('948d90af-2748-5a59-851e-af9ad535992c'::uuid, 'eed8aa68-d129-51c5-855e-1298775ed889'::uuid, 'Comment traduire « il devait avoir vingt ans » ?', 'mcq', '["Tendría veinte años","Tendrá veinte años","Tuvo veinte años","Tenía que tener veinte años"]'::jsonb, 0, 'Conditionnel de probabilité, pour supposer sur le passé.', 8),
    ('3d7abc6d-23aa-55f2-8fde-2d1a9b86f5ac'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'Comment forme-t-on l’impératif négatif ?', 'mcq', '["Avec le subjonctif présent","Avec l’impératif affirmatif précédé de no","Avec l’infinitif","Avec le futur"]'::jsonb, 0, '*No hables*, *no comas*, *no salgáis*.', 1),
    ('fa42cf92-8144-53d1-87e7-35845d1df84c'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'Quel est l’impératif de « hacer » à la deuxième personne du singulier ?', 'mcq', '["Haz","Hace","Haga","Haced"]'::jsonb, 0, 'Comme *di*, *ve*, *pon*, *sal*, *sé*, *ten*, *ven*.', 2),
    ('e8cf9d16-5ba8-5a17-887c-39c36445f66c'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'Après « Te aconsejo que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Te aconsejo que vayas al médico.*', 3),
    ('435cde95-78c7-52a2-953e-7e412ec468d7'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'Comment traduire « tu devrais te reposer » ?', 'mcq', '["Deberías descansar","Debes descansar","Debías descansar","Debe de descansar"]'::jsonb, 0, 'Le conditionnel atténue l’obligation en conseil.', 4),
    ('a9a9ad8a-2ec2-5429-92e5-3493c44d8d40'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, '« Ojalá pudiera ayudarte » exprime un souhait réalisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’imparfait du subjonctif marque au contraire l’improbable.', 5),
    ('4cc8dbcb-8771-5d89-93a6-968561569926'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'Que signifie « Yo que tú, iría al médico » ?', 'mcq', '["À ta place, j’irais chez le médecin","Moi et toi allons chez le médecin","Je te vois chez le médecin","Je dois aller chez le médecin"]'::jsonb, 0, 'La tournure se poursuit au conditionnel.', 6),
    ('84ac6754-faae-5b79-84de-029f3e2641b1'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'L’impératif affirmatif soude les pronoms au verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dímelo* ; au négatif, ils repassent devant : *no me lo digas*.', 7),
    ('dc32ee60-5db5-5350-8c29-c3221b2dc734'::uuid, 'e4c097ef-c2f0-5c6a-90cc-db03c0304747'::uuid, 'Quel mode suit « ¿Y si… ? » pour suggérer ?', 'mcq', '["L’indicatif","Le subjonctif","L’impératif","Le conditionnel"]'::jsonb, 0, '*¿Y si salimos esta noche?*', 8),
    ('f6cf2fc1-45a4-5d84-8288-d5cd25a24f25'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, 'Quelle est la première personne du présent de « hacer » ?', 'mcq', '["Hago","Haco","Hazo","Hacio"]'::jsonb, 0, 'Verbe à *yo* irrégulier : le reste de la conjugaison est régulier.', 1),
    ('56cce1db-9d3b-5ad7-81b3-83e6f422689e'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, 'Quelle est la première personne du présent de « conocer » ?', 'mcq', '["Conozco","Conoco","Conosco","Conogo"]'::jsonb, 0, 'Comme tous les verbes en -cer et -cir : *parezco*, *conduzco*.', 2),
    ('6454b5c1-0a8d-5f66-bfc8-5c29864d15a3'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, '« Ser », « ir », « haber » et « estar » sont totalement irréguliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Soy*, *voy*, *he*, *estoy* : aucune ne suit un modèle.', 3),
    ('57b7caa9-70d3-5520-9bd6-1d6a96c1c719'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, 'Que signifie « Estudio español desde hace dos años » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié l’espagnol il y a deux ans","J’étudierai deux ans","J’étudiais depuis deux ans"]'::jsonb, 0, 'Le présent couvre l’action commencée dans le passé et qui dure.', 4),
    ('e75fd172-281b-513d-8615-a9467d70cac1'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, '« Tener » cumule un yo irrégulier et une diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Tengo*, puis *tienes, tiene… tenemos, tenéis, tienen*.', 5),
    ('2d74ba06-8afc-5f3a-9eae-15e647d99a8a'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, 'Pourquoi « estás » porte-t-il un accent écrit ?', 'mcq', '["L’accent tonique tombe sur la terminaison","C’est un pluriel","Pour le distinguer de « estas »","C’est un subjonctif"]'::jsonb, 0, 'Le second motif est vrai aussi, mais la raison première est prosodique.', 6),
    ('63e0f328-6728-5ad6-8253-fd152e6c96be'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, 'Les verbes en -er et en -ir se conjuguent identiquement au présent, sauf…', 'mcq', '["À nosotros et vosotros","À yo et tú","À él et ellos","Nulle part"]'::jsonb, 0, '*Comemos / vivimos*, *coméis / vivís*.', 7),
    ('ee1a0a3d-7f1b-5140-ba6b-4737aa21fe18'::uuid, '27a109f8-d916-56fc-ad6d-ae40bb389621'::uuid, 'Le présent peut exprimer un futur proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mañana salgo a las ocho.*', 8),
    ('d4b16ac5-e7d6-5d21-9cc5-a646b6dc93ec'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, 'De quelle forme part-on pour construire le subjonctif présent ?', 'mcq', '["De la première personne du présent de l’indicatif","De l’infinitif","Du participe passé","Du passé simple"]'::jsonb, 0, 'On retire le -o et on inverse la voyelle des terminaisons.', 1),
    ('9757b5f9-9c88-5820-b86a-fdd8f59af0a5'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, 'Quelle voyelle prennent les terminaisons du subjonctif des verbes en -ar ?', 'mcq', '["E (hable, hables…)","A","I","O"]'::jsonb, 0, 'Et inversement, les -er et -ir prennent un a : *coma, comas*.', 2),
    ('d3a08319-d9d6-5889-84f4-42032f6ce253'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, 'Quel est le subjonctif présent de « tener » à la première personne ?', 'mcq', '["Tenga","Tena","Tienga","Tuviera"]'::jsonb, 0, 'Il hérite du *yo* irrégulier : *tengo → tenga*.', 3),
    ('c95fdd2d-6a90-5ab0-9659-63c7bfbb31ca'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, 'Après « Cuando » suivi d’une valeur de futur, on emploie…', 'mcq', '["Le subjonctif","Le futur","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — piège majeur du francophone.', 4),
    ('c92acde0-e0a4-5849-aa17-f39d32f85f8d'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, '« Ser », « ir », « haber », « saber », « dar » et « estar » ont un subjonctif irrégulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sea*, *vaya*, *haya*, *sepa*, *dé*, *esté*.', 5),
    ('6ba2b4b0-5c41-5570-ad89-507f9c71873f'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
