    ('f47c6b85-2a29-5514-99d7-f6196d3725b0'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('d948d326-d0e8-5388-b96c-00ead395b4ec'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
